def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_prime_power(n):
    if n <= 1:
        return None # Not a power of a prime
    factors = prime_factorization(n)
    if len(factors) == 1:
        # It is a power of a prime. Return the prime base and its exponent.
        p = list(factors.keys())[0]
        A = list(factors.values())[0]
        return p, A
    else:
        return None, None

solutions = []

for m in range(1, 11):
    for n in range(1, 11):
        X = m**2 + n
        Y = m + n**2

        # Check X = p^A, A >= 2
        pX, AX = is_prime_power(X)

        # Check Y = p^B, B >= 2
        pY, BY = is_prime_power(Y)

        # Check conditions
        if pX is not None and AX >= 2 and pY is not None and BY >= 2:
            if pX == pY:
                p = pX
                solutions.append((m, n, p))

print(solutions)

