import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_power_of_prime(N):
    if N <= 1:
        return None, 0

    # Find potential prime base p
    for p in range(2, int(math.sqrt(N)) + 2):
        if N % p == 0:
            # Check if N is purely a power of p
            temp = N
            count = 0
            while temp > 1 and temp % p == 0:
                temp //= p
                count += 1

            if temp == 1:
                return p, count
    return None, 0

M_MAX = 15
N_MAX = 15
solutions = []

for m in range(1, M_MAX + 1):
    for n in range(1, N_MAX + 1):
        A_val = m*m + n
        B_val = m + n*n

        pA, A = is_power_of_prime(A_val)
        pB, B = is_power_of_prime(B_val)

        # Check constraints: pA and pB must exist, be equal, and exponents A, B must be > 1.
        if pA is not None and pB is not None and pA == pB and A > 1 and B > 1:
            solutions.append((m, n, pA))

print(f"Found solutions (m, n, p) for 1 <= m, n <= {M_MAX}: {solutions}")
